// V2.3 — Contrôles en lecture seule. Aucun enregistrement n'est modifié.
const AUDIT_LABELS={settings:'Paramètres',foods:'Aliments',entries:'Journal',water:'Hydratation',weights:'Poids',recipes:'Recettes',fasting:'Jeûne',plans:'Menus',activities:'Activités'};
function auditDisplay(message){const el=document.querySelector('#auditResult');if(el)el.textContent=message}
function auditCounts(stores){return STORES.map(k=>`${AUDIT_LABELS[k]} : ${stores[k].length}`).join(' · ')}
async function snapshotStores(){return new Promise((resolve,reject)=>{const tx=db.transaction(STORES,'readonly'),stores={},reqs=[];for(const name of STORES){const r=tx.objectStore(name).getAll();reqs.push([name,r])}tx.oncomplete=()=>{for(const [name,r] of reqs)stores[name]=r.result;resolve(stores)};tx.onerror=()=>reject(tx.error||Error('Lecture impossible'));tx.onabort=()=>reject(tx.error||Error('Lecture annulée'))})}
async function auditDatabase(){try{auditDisplay('Contrôle en cours…');const stores=await snapshotStores();validate({app:'NUTRI',version:3,stores});auditDisplay('Base valide. '+auditCounts(stores)+'. Ce contrôle ne remplace pas une sauvegarde externe.')}catch(e){auditDisplay('Anomalie : '+e.message)}}
async function verifyBackupFile(event){const file=event.target.files?.[0];if(!file)return;try{auditDisplay('Vérification en cours…');if(file.size>30*1024*1024)throw Error('Fichier trop volumineux');const wrapper=JSON.parse(await file.text());let data;if(wrapper.format==='NUTRI-ENCRYPTED'){const pass=prompt('Mot de passe du fichier à vérifier :');if(pass===null){auditDisplay('Contrôle annulé');return}try{data=await unseal(wrapper,pass)}catch{throw Error('Mot de passe incorrect ou fichier altéré')}}else{data=wrapper}validate(data);auditDisplay('Fichier valide, sans restauration. '+auditCounts(data.stores)+'. Vérifiez aussi que le fichier est enregistré dans Fichiers ou iCloud Drive.')}catch(e){auditDisplay('Sauvegarde non validée : '+e.message)}finally{event.target.value=''}}


