let quickQuery='',quickRemote=[],quickLoading=false,quickError='',quickTimer=null,quickAbort=null,quickSelected=null;
function quickSearchPage(){return `<div class="add-heading"><button class="back-button" id="quickBack" aria-label="Retour">‹</button><div><div class="eyebrow">Ajouter un aliment</div><h1 class="title">${esc(selectedMeal)}</h1></div></div><div class="quick-search-wrap"><label for="quickFoodInput" class="visually-hidden">Rechercher un aliment</label><input id="quickFoodInput" type="search" autocomplete="off" placeholder="Qu'avez-vous mangé ?" value="${esc(quickQuery)}"><p class="notice">Aliments génériques indicatifs et vos aliments personnels disponibles hors ligne. Produits de marque Open Food Facts en ligne (recherche après 3 caractères). Valeurs génériques approximatives.</p></div><div class="quick-filters"><button class="btn alt small" id="quickFavorites">Favoris et aliments enregistrés</button><button class="btn alt small" id="quickScanner">Code-barres</button></div><div id="quickResults" aria-live="polite"></div><div id="quickPortion" class="quick-portion hidden"></div>`}
function normFood(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,' ').trim()}
async function showQuickResults(){const el=$('#quickResults');if(!el)return;const local=await all('foods');const q=normFood(quickQuery);const rank=f=>{let v=normFood(f.name),a=normFood(f.aliases||'');return v===q?0:v.startsWith(q)?1:v.includes(' '+q)?2:v.includes(q)?3:a.includes(q)?4:5};let items=[...local,...GENERIC_FOODS].filter(f=>!q||(normFood(f.name).includes(q)||normFood(f.aliases||'').includes(q))).sort((a,b)=>rank(a)-rank(b)||a.name.localeCompare(b.name,'fr')).slice(0,35);const seen=new Set();items=items.filter(f=>{let k=normFood(f.name);if(seen.has(k))return false;seen.add(k);return true});const remote=quickRemote.filter(f=>!seen.has(normFood(f.name))).slice(0,25);const rows=(arr,label)=>arr.length?`<h2 class="quick-subtitle">${label}</h2>`+arr.map((f,i)=>`<button class="quick-food" data-quick-source="${label==='Produits en ligne'?'remote':'local'}" data-quick-index="${i}"><span><strong>${esc(f.name)}</strong><small>${esc(f.source||f.brand||'Aliment enregistré')} · pour 100 g</small></span><span class="quick-food-cal">${fmt(f.kcal)} kcal <b>＋</b></span></button>`).join(''):'';el.innerHTML=rows(items,'Aliments')+rows(remote,'Produits en ligne')+(quickLoading?'<p class="notice">Recherche des produits en ligne…</p>':quickError?`<p class="notice">${esc(quickError)}</p>`:'')+(!items.length&&!remote.length&&!quickLoading?'<p class="empty">Aucun résultat. Essayez un autre mot-clé.</p>':'');el.querySelectorAll('[data-quick-source]').forEach(b=>b.onclick=()=>openQuickPortion((b.dataset.quickSource==='remote'?remote:items)[Number(b.dataset.quickIndex)]));}
function openQuickPortion(food){quickSelected=food;const el=$('#quickPortion');el.classList.remove('hidden');el.innerHTML=`<div class="quick-portion-inner"><button id="quickClose" class="quick-close" aria-label="Fermer">×</button><h2>${esc(food.name)}</h2><p class="notice">${fmt(food.kcal)} kcal / 100 g · P ${fmt(food.protein)} g · G ${fmt(food.carbs)} g · L ${fmt(food.fat)} g</p><form id="quickPortionForm"><label class="field">Quantité (g ou ml selon l'aliment)<input id="quickGrams" type="number" min="1" max="10000" step="1" value="100" required></label><p id="quickCalculated" class="quick-calculated">${fmt(food.kcal)} kcal</p><button class="btn full" type="submit">Ajouter au ${esc(selectedMeal)}</button></form></div>`;$('#quickClose').onclick=()=>el.classList.add('hidden');$('#quickGrams').oninput=e=>{$('#quickCalculated').textContent=fmt(n(food.kcal)*n(e.target.value)/100)+' kcal'};$('#quickPortionForm').onsubmit=async e=>{e.preventDefault();const grams=Number($('#quickGrams').value);if(!Number.isFinite(grams)||grams<1||grams>10000)return toast('Quantité invalide');const record={id:uid(),date,meal:selectedMeal,foodId:food.id,name:food.name,grams,kcal:n(food.kcal),protein:n(food.protein),carbs:n(food.carbs),fat:n(food.fat)};try{await put('entries',record);toast('Ajouté au '+selectedMeal);quickSelected=null;tab='home';render()}catch(err){toast('Erreur : '+err.message)}}}
async function fetchQuickRemote(q){if(quickAbort)quickAbort.abort();quickAbort=new AbortController();quickLoading=true;quickError='';quickRemote=[];await showQuickResults();const controller=quickAbort;const timeout=setTimeout(()=>controller.abort(),9000);try{const url=new URL('https://world.openfoodfacts.org/cgi/search.pl');for(const [k,v] of Object.entries({search_terms:q,search_simple:'1',action:'process',json:'1',page_size:'35',fields:'code,product_name,brands,nutriments'}))url.searchParams.set(k,v);const res=await fetch(url,{signal:controller.signal,headers:{Accept:'application/json'}});if(!res.ok)throw Error('service indisponible');const data=await res.json();if(quickQuery!==q)return;quickRemote=(data.products||[]).filter(p=>p.product_name&&p.nutriments&&Number.isFinite(Number(p.nutriments['energy-kcal_100g']))).map(p=>({id:'off:'+p.code,name:String(p.product_name).slice(0,120),source:(p.brands?String(p.brands).slice(0,70)+' · ':'')+'Open Food Facts',...offNutriments(p)}));}catch(err){if(err.name!=='AbortError'&&quickQuery===q)quickError='Produits en ligne indisponibles ; les aliments locaux restent accessibles.'}finally{clearTimeout(timeout);if(quickQuery===q){quickLoading=false;await showQuickResults()}}}
function bindQuickSearch(){if(tab!=='quicksearch')return;$('#quickBack').onclick=()=>{tab='home';quickQuery='';quickRemote=[];render()};$('#quickScanner').onclick=()=>{tab='foods';render();requestAnimationFrame(()=>$('#barcodeInput')?.focus())};$('#quickFavorites').onclick=async()=>{const list=await all('foods');quickQuery='';quickRemote=[];const el=$('#quickResults');el.innerHTML='<h2 class="quick-subtitle">Mes aliments enregistrés</h2>'+list.map((f,i)=>`<button class="quick-food" data-fav="${i}"><strong>${esc(f.name)}</strong><span>${fmt(f.kcal)} kcal ＋</span></button>`).join('');if(!list.length)el.innerHTML='<p class="empty">Aucun aliment enregistré pour le moment.</p>';el.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>openQuickPortion(list[Number(b.dataset.fav)]))};const input=$('#quickFoodInput');input.addEventListener('input',()=>{quickQuery=input.value.trim().slice(0,100);quickRemote=[];quickError='';if(quickAbort)quickAbort.abort();clearTimeout(quickTimer);showQuickResults();if(quickQuery.length>=3)quickTimer=setTimeout(()=>fetchQuickRemote(quickQuery),1100)});showQuickResults();}
